package batch

import (
 "context"
 "log"
)

type Task struct {
 Name string
 Run func(context.Context) error
}

func Execute(ctx context.Context, prepare func(context.Context) error, tasks []Task) error {
 if err := prepare(ctx); err != nil {
  log.Printf("prepare failed: %v", err)
  return err
 }
 for _, task := range tasks {
  if err := task.Run(ctx); err != nil {
   log.Printf("task failed: %v", err)
   return err
  }
 }
 return nil
}

