package main

import (
 "context"
 "log"
 "os"
 batch "example.com/batch"
)

func main() {
 if err := batch.Execute(context.Background(), func(context.Context) error { return nil }, nil); err != nil {
  log.Printf("batch failed: %v", err)
  os.Exit(1)
 }
}

