package implementers

import "fmt"

type GitHub struct { Owner string }
func (g GitHub) Label() string { return "github/" + g.Owner }

type GitLab struct { Group string }
func (g GitLab) Label() string { return "gitlab/" + g.Group }

type Kubernetes struct { Namespace string }
func (k Kubernetes) Label() string { return "k8s/" + k.Namespace }

func Label(provider, name string) (string, error) {
 switch provider {
 case "github": return (GitHub{Owner: name}).Label(), nil
 case "gitlab": return (GitLab{Group: name}).Label(), nil
 case "k8s": return (Kubernetes{Namespace: name}).Label(), nil
 default: return "", fmt.Errorf("unsupported provider %q", provider)
 }
}

